import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";

export type Invoice = {
  id: string;
  customerId: string;
  totalCents: number;
  dueDate: string;
};

export type ExportRecord = {
  invoiceId: string;
  path: string;
  bytesWritten: number;
};

export function renderInvoice(invoice: Invoice): string {
  return [invoice.id, invoice.customerId, invoice.totalCents, invoice.dueDate].join("|");
}

export class InvoiceExporter {
  private readonly outputDir: string;

  constructor(outputDir: string) {
    this.outputDir = outputDir;
  }

  async exportAll(invoices: Invoice[]): Promise<ExportRecord[]> {
    await mkdir(this.outputDir, { recursive: true });
    const exported: ExportRecord[] = [];

    for (const invoice of invoices) {
      const path = join(this.outputDir, `${invoice.id}.pdf`);
      const body = renderInvoice(invoice);

      try {
        await writeFile(path, body, "utf8");
        exported.push({ invoiceId: invoice.id, path, bytesWritten: body.length });
      } catch {
      }
    }

    return exported;
  }
}

