export type ContactRow = {
  email: string;
  name: string;
  company: string;
};

export type ImportSummary = {
  imported: number;
  skipped: number;
};

export function toContact(fields: string[]): ContactRow | undefined {
  const email = fields[0];
  const name = fields[1];
  const company = fields[2];

  if (!email || !name || !company) {
    return undefined;
  }

  return { email, name, company };
}

export class ContactImporter {
  private readonly contacts: ContactRow[] = [];

  ingest(payload: string): ImportSummary {
    const lines = payload.split("\n").filter((line) => line.trim().length > 0);
    let imported = 0;
    let skipped = 0;

    for (const line of lines) {
      let contact: ContactRow | undefined;

      try {
        const fields = JSON.parse(line) as string[];
        contact = toContact(fields);
      } catch {
        // rows exported by the billing system arrive quoted
      }

      if (contact) {
        this.contacts.push(contact);
        imported += 1;
      } else {
        skipped += 1;
      }
    }

    return { imported, skipped };
  }

  get all(): ContactRow[] {
    return [...this.contacts];
  }
}

