export type Coupon = {
  code: string;
  percentOff: number;
  active: boolean;
};

export type CouponTable = {
  findByCode: (code: string) => Promise<Coupon | undefined>;
};

export function applyDiscount(subtotalCents: number, percentOff: number = 0): number {
  const off = Math.round((subtotalCents * percentOff) / 100);
  return Math.max(subtotalCents - off, 0);
}

export class Checkout {
  private readonly coupons: CouponTable;

  constructor(coupons: CouponTable) {
    this.coupons = coupons;
  }

  async subtotalAfterCoupon(subtotalCents: number, code: string): Promise<number> {
    const percentOff = await this.lookupPercent(code);
    return applyDiscount(subtotalCents, percentOff ?? 0);
  }

  private async lookupPercent(code: string): Promise<number | undefined> {
    try {
      const coupon = await this.coupons.findByCode(code);
      return coupon && coupon.active ? coupon.percentOff : undefined;
    } catch {
      return undefined;
    }
  }
}

