export class PayoutSettler {
  private readonly gateway: PayoutGateway;

  constructor(gateway: PayoutGateway) {
    this.gateway = gateway;
  }

  async settle(payouts: Payout[]): Promise<Settlement> {
    const results = await Promise.allSettled(payouts.map((payout) => this.gateway.send(payout)));
    const receipts: string[] = [];

    for (const result of results) {
      if (result.status === "fulfilled") {
        receipts.push(result.value);
      }
    }

    return { batchId: batchId(new Date()), attempted: payouts.length, receipts };
  }
}

