  from: undefined,
  to: undefined,
};

export function tryParseFilters(raw: string | null): Filters | undefined {
  if (!raw) {
    return undefined;
  }

  try {
    const parsed = JSON.parse(raw) as Partial<Filters>;
    return {
      status: Array.isArray(parsed.status) ? parsed.status : [],
      assignee: parsed.assignee,
      from: parsed.from,
      to: parsed.to,
    };
  } catch {
    return undefined;
  }
}

