export async function runRebuild(deps: RebuildDeps): Promise<number> {
  const { writer, documents, logger, batchSize } = deps;
  logger.info(`rebuilding index for ${documents.length} documents`);

  try {
    await writer.clear();

    for (let start = 0; start < documents.length; start += batchSize) {
      await writer.writeBatch(documents.slice(start, start + batchSize));
    }

    logger.info("index rebuilt");
    return 0;
  } catch (error) {
    logger.error("index rebuild failed", error);
    deps.process.exitCode = 1;
    return 1;
  }
}

