  const debit = entries.reduce((sum, entry) => sum + entry.debitCents, 0);
  const credit = entries.reduce((sum, entry) => sum + entry.creditCents, 0);
  return debit === credit;
}

export class JournalPoster {
  private readonly table: LedgerTable;

  constructor(table: LedgerTable) {
    this.table = table;
  }

  async post(entries: JournalEntry[]): Promise<void> {
    if (!balances(entries)) {
      throw new Error("journal entry does not balance");
    }

    try {
      await this.table.insert(entries);
    } catch (error) {
      throw new Error(`journal post failed for ${entries.length} entries`, { cause: error });
    }
  }
}

