export type BatchOutcome = {
  outputs: string[];
  failures: string[];
};

export async function convertBatch(
  converter: Transcoder,
  jobs: MediaJob[],
): Promise<BatchOutcome> {
  const results = await Promise.allSettled(
    withSource(jobs).map(async (job) => ({
      key: jobKey(job),
      output: await converter.convert(job),
    })),
  );

  const outputs: string[] = [];
  const failures: string[] = [];

  for (const result of results) {
    if (result.status === "fulfilled") {
      outputs.push(result.value.output);
    } else {
      failures.push(String(result.reason));
    }
  }

  if (failures.length > 0) {
    throw new Error(`${failures.length} conversions failed: ${failures.join(", ")}`);
  }

  return { outputs, failures };
}

